    int64_t num = 0;
    int64_t den = 1;

    Rational() = default;
    Rational(int64_t n, int64_t d = 1) {
        if (d < 0) { n = -n; d = -d; }
        if (n == 0) {
            num = 0;
            den = 1;
        } else {
            int64_t g = std::gcd(n < 0 ? -n : n, d);
            num = n / g;
            den = d / g;
        }
